    const real_t delta_rho_in = rho_in - 1;
    const real_t x0 = ((ux_in) * (ux_in));
    const real_t x1 = (1.0F/3.0F)*rho_in;
    const real_t x2 = ((uy_in) * (uy_in));
    const real_t x3 = ((uz_in) * (uz_in));
    const real_t x4 = uy_in*x1;
    const real_t x5 = (1.0F/6.0F)*rho_in;
    const real_t x6 = -x0*x5;
    const real_t x7 = (1.0F/9.0F)*delta_rho_in;
    const real_t x8 = -x3*x5 + x7;
    const real_t x9 = x6 + x8;
    const real_t x10 = -x1;
    const real_t x11 = ux_in*x1;
    const real_t x12 = -x2*x5;
    const real_t x13 = x12 + x8;
    const real_t x14 = uz_in*x1;
    const real_t x15 = x12 + x6 + x7;
    const real_t x16 = (1.0F/24.0F)*rho_in;
    const real_t x17 = ux_in*x16;
    const real_t x18 = (1.0F/8.0F)*rho_in;
    const real_t x19 = uy_in*x18;
    const real_t x20 = uz_in*x18;
    const real_t x21 = x16 + x20;
    const real_t x22 = x19 + x21;
    const real_t x23 = uy_in*x16;
    const real_t x24 = (1.0F/72.0F)*delta_rho_in;
    const real_t x25 = uz_in*x16;
    const real_t x26 = uz_in*(x16 + x25) + x24;
    const real_t x27 = uy_in*(x21 + x23) + x26;
    const real_t x28 = x17 - x19;
    const real_t x29 = uy_in*((1.0F/24.0F)*rho_in*uy_in - x21) + x26;
    const real_t x30 = -x16;
    const real_t x31 = -x20;
    const real_t x32 = x17 + x19;
    const real_t x33 = x16 + x31;
    const real_t x34 = uz_in*(x25 + x30) + x24;
    const real_t x35 = uy_in*(x23 + x33) + x34;
    const real_t x36 = x20 + x30;
    const real_t x37 = uy_in*(x23 + x36) + x34;
    g[7] = (2.0F/9.0F)*delta_rho_in - x0*x1 - x1*x2 - x1*x3;
    g[9] = uy_in*(x1 + x4) + x9;
    g[5] = uy_in*(x10 + x4) + x9;
    g[6] = ux_in*(x10 + x11) + x13;
    g[8] = ux_in*(x1 + x11) + x13;
    g[12] = uz_in*(x1 + x14) + x15;
    g[2] = uz_in*(x10 + x14) + x15;
    g[14] = ux_in*(x17 + x22) + x27;
    g[13] = ux_in*((1.0F/24.0F)*rho_in*ux_in - x22) + x27;
    g[11] = ux_in*(x21 + x28) + x29;
    g[10] = ux_in*(x30 + x31 + x32) + x29;
    g[4] = ux_in*(x32 + x33) + x35;
    g[3] = ux_in*(x28 + x36) + x35;
    g[1] = ux_in*(x28 + x33) + x37;
    g[0] = ux_in*(x32 + x36) + x37;
}

constexpr void calc_rho_u(real_t& rho_out, real_t& ux_out, real_t& uy_out, real_t& uz_out, const ddf_t (&g)[15])
{
    const ddf_t f_0 = g[7];
    const ddf_t f_1 = g[9];
    const ddf_t f_2 = g[5];
    const ddf_t f_3 = g[6];
    const ddf_t f_4 = g[8];
    const ddf_t f_5 = g[12];
    const ddf_t f_6 = g[2];
    const ddf_t f_7 = g[14];
    const ddf_t f_8 = g[13];
    const ddf_t f_9 = g[11];
    const ddf_t f_10 = g[10];
    const ddf_t f_11 = g[4];
    const ddf_t f_12 = g[3];
    const ddf_t f_13 = g[1];
    const ddf_t f_14 = g[0];
    const real_t x0 = f_14 + f_3;
    const real_t x1 = f_1 + f_11;
    const real_t x2 = f_5 + f_8 + f_9;
    const real_t x3 = f_0 + f_10 + f_12 + f_13 + f_2 + f_4 + f_6 + f_7 + x0 + x1 + x2 + 1;
    const real_t x4 = (1.0f / ((x3)));
    const real_t x5 = -f_13;
    const real_t x6 = f_12 + f_8 - f_9 + x5;
    const real_t x7 = f_10 - f_11;
    const real_t x8 = -f_14 + f_7;
    rho_out = x3;
    ux_out = x4*(f_4 + f_7 - x0 - x6 - x7);
    uy_out = x4*(-f_10 - f_2 + x1 + x6 + x8);
    uz_out = x4*(-f_12 - f_6 + x2 + x5 + x7 + x8);
}
}
